        /// <summary>Metrics measured offline for the prefab called <paramref name="prefabName"/> (file name without extension).</summary>
        public static bool TryGet(string prefabName, out PropMetrics metrics)
        {
            metrics = default;
            return prefabName != null && Table.TryGetValue(prefabName, out metrics);
        }

        /// <summary>Metrics for a catalog asset path (e.g. <c>.../SM_Env_Rock_01.prefab</c>).</summary>
        public static bool TryGetForPath(string assetPath, out PropMetrics metrics)
        {
            metrics = default;
            if (string.IsNullOrEmpty(assetPath)) return false;
            int slash = assetPath.LastIndexOf('/');
            int dot = assetPath.LastIndexOf('.');
            string name = assetPath.Substring(slash + 1, (dot > slash ? dot : assetPath.Length) - slash - 1);
            return TryGet(name, out metrics);
        }

        /// <summary>Every prefab name in the table.</summary>
        public static IEnumerable<string> Names => Table.Keys;

        private static PropMetrics M(float minX, float minY, float minZ, float maxX, float maxY, float maxZ, float face, params float[] underside) =>
            new PropMetrics(new Vector3(minX, minY, minZ), new Vector3(maxX, maxY, maxZ), face, underside);
    }
}
